"use client";
// The phone field on every svasamm.com form (Mithun, 10 Nov 2026): a country picker, India first,
// then every country A–Z; the dial code shown is the chosen country's, and the number is checked
// against that country's lengths. The list is lib/countries.json, generated by web-dev
// tools/gen_countries.py from Google's libphonenumber — the same file t4suite.com and lucoze.com use.
import COUNTRIES from "@/lib/countries.json";

export type Country = { c: string; n: string; d: string; f: string; min: number; max: number };
export const ALL: Country[] = COUNTRIES as Country[];
const BY_CODE: Record<string, Country> = Object.fromEntries(ALL.map((x) => [x.c, x]));

/** What was typed, without the country's own code if the person typed it too ("+91 98300…"). */
const withoutCode = (k: Country, v: string) => v.trim().replace(new RegExp(`^\\+\\s*${k.d}[\\s-]*`), "");

/** The national digits: spaces, dashes, a typed "+<code>" and a leading trunk 0 dropped. */
export const nationalDigits = (v: string, k: Country = BY_CODE.IN) => withoutCode(k, v).replace(/\D/g, "").replace(/^0/, "");

/** A number this country could have. India also keeps its own rule: 10 digits, never starting with 0. */
export function validPhone(cc: string, v: string): boolean {
  const k = BY_CODE[cc] ?? BY_CODE.IN;
  const n = nationalDigits(v, k).length;
  return n >= k.min && n <= k.max;
}

/** What the server receives: "+91 98300 12345" — the dial code, then what was typed. */
export function fullNumber(cc: string, v: string): string {
  const k = BY_CODE[cc] ?? BY_CODE.IN;
  return `+${k.d} ${withoutCode(k, v).replace(/^0/, "")}`;
}

export default function PhoneField({
  id, label, cc, value, onCountry, onNumber, error, required, placeholder,
}: {
  id: string; label: string; cc: string; value: string;
  onCountry: (cc: string) => void; onNumber: (v: string) => void;
  error?: string | false; required?: boolean; placeholder?: string;
}) {
  const k = BY_CODE[cc] ?? BY_CODE.IN;
  return (
    <div className="sv-field">
      <label htmlFor={id}>
        {label}
        {required && <span className="sv-req" aria-hidden="true"> *</span>}
      </label>
      <div style={{ display: "flex", gap: 8 }}>
        {/* The closed picker shows only "🇮🇳 +91"; the native list underneath carries the names,
            so it opens the phone's own picker and is searchable by typing. */}
        <div className="sv-input sv-cc" style={{ position: "relative", flex: "0 0 auto", width: "auto", minWidth: "max-content", paddingLeft: 12, display: "flex", alignItems: "center", gap: 4, paddingRight: 8, whiteSpace: "nowrap" }}>
          <span aria-hidden="true">{k.f} +{k.d}</span>
          <svg aria-hidden="true" width="12" height="12" viewBox="0 0 12 12" style={{ color: "var(--sv-ink-3)" }}>
            <path d="M3 4.5 6 7.5 9 4.5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <select
            id={`${id}-cc`}
            aria-label={`Country code, now ${k.n} +${k.d}`}
            value={k.c}
            onChange={(e) => onCountry(e.target.value)}
            style={{ position: "absolute", inset: 0, opacity: 0, width: "100%", cursor: "pointer" }}
          >
            {ALL.map((x) => (
              <option key={x.c} value={x.c}>{`${x.f} ${x.n} (+${x.d})`}</option>
            ))}
          </select>
        </div>
        <input
          id={id}
          className="sv-input"
          type="tel"
          inputMode="tel"
          autoComplete="tel-national"
          value={value}
          onChange={(e) => onNumber(e.target.value)}
          placeholder={placeholder ?? (k.c === "IN" ? "98300 12345" : `${k.min === k.max ? k.min : `${k.min}–${k.max}`} digits`)}
          aria-required={required || undefined}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? `${id}-err` : undefined}
          style={{ flex: 1, minWidth: 0 }}
        />
      </div>
      {error && (
        <span id={`${id}-err`} role="alert" style={{ fontSize: 12.5, color: "#b42318", marginTop: 5, display: "block" }}>
          {error}
        </span>
      )}
    </div>
  );
}
